import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;

/**
 * CBACT02C - CardDemo card master sequential reader.
 *
 * Faithful translation of COBOL module CBACT02C (examples/real/CBACT02C.cbl,
 * sha256 90ca766e...). The COBOL program opens an indexed CARDFILE, reads each
 * record, DISPLAYs it, then closes the file. There are no ACCEPT statements, so
 * the card records are consumed from stdin (one raw record per line, in file
 * order) and each read record is echoed to stdout exactly as COBOL's
 * DISPLAY CARD-RECORD would emit the 150-byte group item.
 */
public final class Cbact02c {

    /** FD-CARDFILE-REC / CARD-RECORD group width, PIC X(150 total). */
    private static final int RECORD_WIDTH = 150;

    /** CARDFILE-STATUS, PIC XX (file status pair). */
    private String cardfileStatus = "00";

    /** IO-STATUS, PIC XX. */
    private String ioStatus = "00";

    /** END-OF-FILE, PIC X(01) VALUE 'N'. */
    private String endOfFile = "N";

    /** APPL-RESULT, PIC S9(9) COMP. */
    private int applResult = 0;

    /** CARD-RECORD group image, PIC X(150). */
    private String cardRecord = "";

    private final BufferedReader in;

    private Cbact02c(BufferedReader in) {
        this.in = in;
    }

    public static void main(String[] args) {
        var app = new Cbact02c(
                new BufferedReader(new InputStreamReader(System.in, StandardCharsets.UTF_8)));
        app.mainline();
    }

    // MAINLINE PARAGRAPH (CBACT02C.cbl lines 70-174, driver body 71-87).
    private void mainline() {
        System.out.println("START OF EXECUTION OF PROGRAM CBACT02C");

        cardfileOpen();

        // Inline PERFORM UNTIL END-OF-FILE = 'Y' (lines 74-81).
        while (!endOfFile.equals("Y")) {
            if (endOfFile.equals("N")) {
                cardfileGetNext();
                if (endOfFile.equals("N")) {
                    System.out.println(cardRecord); // DISPLAY CARD-RECORD (line 78)
                }
            }
        }

        cardfileClose();

        System.out.println("END OF EXECUTION OF PROGRAM CBACT02C");
        // GOBACK (line 87) - normal termination, exit 0.
    }

    // 1000-CARDFILE-GET-NEXT (CBACT02C.cbl lines 92-116).
    private void cardfileGetNext() {
        // READ CARDFILE-FILE INTO CARD-RECORD (line 93).
        String line = readLine();
        if (line == null) {
            cardfileStatus = "10"; // at end
        } else {
            cardfileStatus = "00";
            cardRecord = fit(line, RECORD_WIDTH);
        }

        // Settle file status into APPL-RESULT (lines 94-103).
        if (cardfileStatus.equals("00")) {
            applResult = 0;
        } else if (cardfileStatus.equals("10")) {
            applResult = 16;
        } else {
            applResult = 12;
        }

        // React to APPL-RESULT (lines 104-115).
        if (applResult == 0) {
            // normal, continue
        } else if (applResult == 16) {
            endOfFile = "Y"; // MOVE 'Y' TO END-OF-FILE (line 108)
        } else {
            System.out.println("ERROR READING CARDFILE");
            ioStatus = cardfileStatus;
            displayIoStatus();
            abendProgram();
